import { PDFDocument, StandardFonts, rgb, PDFName, PDFArray } from 'pdf-lib';
import { BorrowRequest, User, Storage } from './storage'; // <-- Tambah Storage di sini


// Fungsi untuk tukar YYYY-MM-DD kepada DD-MM-YYYY
function formatDate(dateStr: string): string {
  if (!dateStr) return '';
  // Asingkan jika ada huruf 'T' (kes Next.js ISO String) dan split guna '-'
  const parts = dateStr.split('T')[0].split('-');
  if (parts.length === 3) {
    const [year, month, day] = parts;
    return `${day}-${month}-${year}`; // Susun balik jadi DD-MM-YYYY
  }
  return dateStr; // Pulangkan asal jika format tak padan
}

function base64ToArrayBuffer(base64: string): ArrayBuffer {
  const binaryString = window.atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
}

export async function printBorangKEWPA9(req: BorrowRequest, currentUser: User, allUsers: User[]) {
  try {
    // ─── ⚠️ PASTIKAN BASE64 BORANG SEBENAR ANDA KEKAL DI SINI ───
    const b64Data = ""; 


    const existingPdfBytes = base64ToArrayBuffer(b64Data);

    const pdfDoc = await PDFDocument.load(existingPdfBytes);
    const pages = pdfDoc.getPages();
    const firstPage = pages[0]; 
    const { width, height } = firstPage.getSize(); 

    // FIX: Selesaikan isu 'Contents.push is not a function'
    const pageNode = firstPage.node as any;
    if (pageNode.Contents()) {
      const contentsKey = PDFName.of('Contents');
      const Contents = pageNode.get(contentsKey);
      if (Contents && !(Contents instanceof PDFArray)) {
        const array = pdfDoc.context.obj([Contents]);
        pageNode.set(contentsKey, array);
      }
    }

    const font = await pdfDoc.embedFont(StandardFonts.Helvetica);
    const fontSize = 10;

    const draw = (text: string, x: number, y: number, size = fontSize) => {
      if (!text) return;
      firstPage.drawText(text, { x, y: height - y, size, font, color: rgb(0, 0, 0) });
    };

    // ─── 🛠️ MODIFIKASI: GRID HALUS HIGH-PRECISION (SETIAP 20 UNIT) ───
    const paparkanGrid = false; 

    if (paparkanGrid) {
      // Garisan Menegak (Paksi X)
      for (let x = 0; x < width; x += 20) {
        const isMajor = x % 100 === 0;
        firstPage.drawLine({
          start: { x, y: 0 },
          end: { x, y: height },
          thickness: isMajor ? 0.4 : 0.15,
          color: isMajor ? rgb(0.8, 0.2, 0.2) : rgb(0.9, 0.6, 0.6)
        });
        // Papar nombor setiap 40 unit supaya tidak terlalu padat
        if (x % 40 === 0) {
          firstPage.drawText(x.toString(), { x: x + 2, y: height - 12, size: 6, font, color: rgb(0.7, 0.2, 0.2) });
        }
      }
      
      // Garisan Melintang (Paksi Y)
      for (let y = 0; y < height; y += 20) {
        const isMajor = y % 100 === 0;
        firstPage.drawLine({
          start: { x: 0, y: height - y },
          end: { x: width, y: height - y },
          thickness: isMajor ? 0.4 : 0.15,
          color: isMajor ? rgb(0.8, 0.2, 0.2) : rgb(0.9, 0.6, 0.6)
        });
        if (y % 40 === 0) {
          firstPage.drawText(y.toString(), { x: 4, y: height - y + 2, size: 6, font, color: rgb(0.7, 0.2, 0.2) });
        }
      }
    }
    // ─────────────────────────────────────────────────────────────────

    const requester = allUsers.find(u => u.uid === req.userId) || currentUser;

    // ─── MAKLUMAT PEMOHON (Sila adjust guna grid halus baru) ───
    draw(req.userName || '', 160, 183);                          // Nama Pemohon (Moon) [cite: 47]
    draw(req.purpose || '', 410, 182);                           // Tujuan (Meeting) [cite: 54, 55]
    draw((requester as any).jawatan || '', 160, 210);            // Jawatan (My Step) [cite: 49, 50]
    draw((req as any).location || req.userDept || '', 410, 210);   // Tempat Digunakan (Centella) [cite: 56, 57]
    draw(req.userDept || '', 160, 235);                          // Bahagian (Operasi) [cite: 51, 52]
    
    if (currentUser.role === 'admin') {
      draw(currentUser.name || '', 410, 235);                    // Nama Pengeluar (Admin IT) [cite: 58, 59]
    }

// ─── JADUAL ASET (Koordinat Emas Anda Dijamin Kekal) ───
    const startY = 340;   
    const rowHeight = 25; 
    
    // 1. Tarik semua data aset dari storage secara "background" untuk dapatkan kategori
    const allAssets = await Storage.getAssets().catch(() => []);

    if (req.items && req.items.length > 0) {
      req.items.forEach((item, index) => {
        const yPos = startY + (index * rowHeight);
        
        // 2. Cari aset yang sepadan dengan item pinjaman untuk intip kategorinya
        const matchedAsset = allAssets.find(a => a.assetId === item.assetId);
        const namaKategori = matchedAsset?.category || item.assetName || ''; 
        
        draw((index + 1).toString(), 52, yPos);                                                   // Bil 
        draw(item.assignedSerialNumber || item.assignedAssetTag || '................', 80, yPos);  // No. Siri 
        
        // 3. Cetak nama kategori yang berjaya dikesan pada koordinat X: 159
        draw(namaKategori, 159, yPos);
        
        draw(formatDate(req.borrowDate || ''), 243, yPos);                                        // Tarikh Dipinjam  
        draw(formatDate(req.returnDate || ''), 302, yPos);                                        // Tarikh Pulang 
        
        const statusText = item.status === 'approved' ? 'Lulus' : item.status === 'rejected' ? 'Gagal' : '';
        draw(statusText, 360, yPos);                                                              // Status 
      });
    }
    

    // ─── RUANGAN TANDATANGAN (Sila laras koordinat baris guna grid baru) ───
    const namaY = 545;
    const jawatanY = 562;
    const tarikhY = 580;
    
    // Blok Peminjam (Kiri)
    draw(req.userName || '', 115, namaY);                     // Nama 
    draw((requester as any).jawatan || '', 115, jawatanY);       // Jawatan 
                      // Tarikh 
    draw(formatDate(req.borrowDate || ''), 115, tarikhY);

    // Blok Pelulus (Kanan)
    if (currentUser.role === 'admin') {
      draw(currentUser.name || '', 360, namaY);               // Nama 
      draw((currentUser as any).jawatan || '', 360, jawatanY);   // Jawatan 
                       // Tarikh 
      draw(formatDate(req.borrowDate || ''), 360, tarikhY);
    }
    
    // 3. Proses Muat Turun
    const pdfBytes = await pdfDoc.save();
    const blob = new Blob([pdfBytes as any], { type: 'application/pdf' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `KEW-PA9-${req.requestId}.pdf`;
    link.click();

  } catch (error) {
    console.error("Ralat janaan PDF:", error);
    alert("Gagal memproses fail templat data.");
  }
}